[
  {
    "question": "Why is WSL2 still recommended over native Windows when using the web dashboard's chat interface?",
    "answer": "While native Windows is officially supported, the web dashboard's Chat tab embeds a full terminal that requires a POSIX PTY, making WSL2 preferred for that specific interface pane.",
    "evidence": [
      "`website/docs/user-guide/features/web-dashboard.md:70` documents the Dashboard **Chat** tab, which embeds the full Hermes TUI directly in the browser.",
      "the dashboard `/chat` embedded terminal requires a POSIX PTY, so WSL2 is still preferred for that pane."
    ]
  },
  {
    "question": "What messaging platform file-handling improvements were introduced in release v2026.7.1 for Discord and Matrix?",
    "answer": "Release v2026.7.1 enabled inbound file attachments (including Python scripts) to be cached and injected into prompts for Discord, while strengthening outbound file delivery for Matrix using m.file media uploads.",
    "evidence": [
      "Commit `4314d451c` (`fix(gateway): accept any inbound file type across all messaging platforms`) made authorized Discord uploads of any file type cacheable and available to the agent.",
      "`plugins/platforms/matrix/adapter.py:1950` uploads documents as Matrix `m.file` media; `tools/send_message_tool.py:1734-1748` dispatches Matrix media files to that method."
    ]
  },
  {
    "question": "Which release version introduced both multi-arch ARM64 Docker images and the pluggable ContextEngine interface?",
    "answer": "Both multi-architecture ARM64 Docker support and the pluggable ContextEngine interface were introduced in release v2026.4.13.",
    "evidence": [
      "ARM64/v8 support was added in PR #6124 (`18140199c`) and shipped in release **v2026.4.13**.",
      "`fe7e6c156cf3628ef63fff6acfe4448ffb24faf3` (`feat: add ContextEngine ABC, refactor ContextCompressor to inherit from it`) and is contained in release `v2026.4.13`."
    ]
  },
  {
    "question": "What improvements to Ollama Cloud connectivity and Discord setup were delivered in Hermes Agent v0.15.0 (v2026.5.28)?",
    "answer": "Hermes Agent v0.15.0 (v2026.5.28) added default routing to https://ollama.com/v1 for Ollama Cloud and introduced the interactive hermes gateway setup wizard for Discord platform credentials.",
    "evidence": [
      "reported Ollama Cloud routing issue is already fixed on main and shipped in v2026.5.28 (Hermes Agent v0.15.0).",
      "`hermes gateway setup` is registered as a gateway subcommand for configuring messaging platforms: `hermes_cli/subcommands/gateway.py:213`."
    ]
  },
  {
    "question": "How are subagents executed and configured for multi-agent task delegation in Hermes Agent?",
    "answer": "Subagents are spawned as isolated child AIAgent instances using the delegate_task tool (supporting up to 3 concurrent subagents by default), and their model and provider settings are configured via delegation.provider and delegation.model in config.yaml.",
    "evidence": [
      "The supported configuration point for subagents remains `delegation.provider` / `delegation.model` in `config.yaml`.",
      "**Multi-agent communication** is handled by the `delegate_task` tool:\n- Spawns isolated child AIAgent instances with their own context, toolsets, and terminal sessions"
    ]
  },
  {
    "question": "What CLI command can be used both to disable unneeded toolsets for small local models and to enable the bundled Langfuse observability plugin?",
    "answer": "The `hermes tools` command can be used to disable unused toolsets to optimize token usage for small local models, and it can also be used to enable the bundled Langfuse plugin.",
    "evidence": [
      "- Reduce toolsets: `hermes tools` → disable toolsets you don't need",
      "`plugins/observability/langfuse/README.md:3-17` documents enabling it with `hermes tools` or `hermes plugins enable observability/langfuse`."
    ]
  },
  {
    "question": "Where should user-created standalone plugins, such as custom tools or out-of-tree memory providers, be placed?",
    "answer": "Standalone plugins, including out-of-tree memory providers and custom tools, should be placed in `~/.hermes/plugins/` (or installed via pip) and enabled in `plugins.enabled` or via `hermes plugins enable`.",
    "evidence": [
      "Publish as standalone plugin into `~/.hermes/plugins/` or via pip entry point. Must implement `MemoryProvider` ABC (`sync_turn`, `prefetch`, `shutdown`, optional `post_setup`).",
      "user plugins are scanned from `~/.hermes/plugins` in `hermes_cli/plugins.py:1192`, and standalone/user plugins are opt-in via `plugins.enabled` with a clear `hermes plugins enable ...` message"
    ]
  },
  {
    "question": "What two Telegram-related capabilities were added or improved in release v2026.5.7?",
    "answer": "Release v2026.5.7 enabled sending MCP tool image results natively to Telegram via MEDIA tags and added session preservation during restarts by marking crash-interrupted conversations as resume_pending.",
    "evidence": [
      "`c8e3e3918509d4c43432ec2cf19ef6a1cfe9cd9c` (`fix(mcp): surface image tool results as MEDIA tags instead of dropping them (#21328)`), shipped in `v2026.5.7`.",
      "`f1e029251` changed crash/restart handling from blanket suspension to `resume_pending`, preserving the existing conversation instead of wiping it; it shipped in `v2026.5.7`."
    ]
  },
  {
    "question": "How can an OpenAI-compatible vision model running on a custom endpoint be configured so Hermes uses the local base URL and enables native image payloads?",
    "answer": "Set `provider: custom` to force Hermes to use the local base_url rather than auto-detecting credentials, and configure `supports_vision: true` to enable native vision payloads on custom OpenAI-compatible endpoints.",
    "evidence": [
      "Setting `provider: custom` forces Hermes to use your `base_url` instead of auto-detecting from environment variables.",
      "PR #17936 implements a config-level override. Once merged, setting `supports_vision: true` in your model config should enable native image payloads for Ollama vision models."
    ]
  },
  {
    "question": "Where does Hermes Agent persist user profile information versus skill usage tracking data?",
    "answer": "User profile attributes and preferences are saved to `USER.md` (using target=\"user\"), while skill execution metrics and timestamps are tracked in `~/.hermes/skills/.usage.json`.",
    "evidence": [
      "`tools/memory_tool.py:5` and `:280` define `USER.md` as the persistent user-profile store and map `target=\"user\"` to that file",
      "`tools/skill_usage.py:1` documents the skill usage sidecar at `~/.hermes/skills/.usage.json`, including `use_count`, `view_count`, and timestamps."
    ]
  },
  {
    "question": "How does Hermes Agent prevent runaway conversation loops and manage context window bloat caused by excessive tool outputs?",
    "answer": "Hermes bounds maximum turns using `agent.max_turns` (defaulting to 90), while `ContextCompressor` prunes and compacts older verbose tool results to prevent token window saturation.",
    "evidence": [
      "`agent.max_turns` defaults to 90 and can be changed in config; `hermes chat --max-turns <N>` overrides it for one conversation turn",
      "`agent/context_compressor.py:1269` prunes/deduplicates old verbose tool results while retaining a token-budgeted recent tail"
    ]
  },
  {
    "question": "How does Hermes Agent automatically handle API keys and token usage tracking when connecting to local backend services like Honcho and OpenAI-compatible providers?",
    "answer": "Hermes automatically injects \"local\" as a placeholder API key for Honcho connections pointing to localhost/127.0.0.1, and sends `stream_options={\"include_usage\": true}` on streaming OpenAI-compatible requests to ensure token tracking functions.",
    "evidence": [
      "Injects `\"local\"` as a placeholder API key at SDK-client init time whenever `base_url` points to `localhost`, `127.0.0.1`, or `::1`",
      "`agent/chat_completion_helpers.py:2222-2229` now sends `stream_options={\"include_usage\": true}` for streaming OpenAI-compatible chat-completions requests"
    ]
  },
  {
    "question": "What configuration mechanisms allow Hermes Agent to isolate different user profiles on gateway platforms while also customizing personas per channel?",
    "answer": "Gateway profile multiplexing isolates credentials, sessions, and memory per user profile under a single gateway process, while `channel_prompts` allows defining distinct system prompt personas for individual channel IDs.",
    "evidence": [
      "`gateway/run.py:8455` starts enabled adapters for secondary profiles under each profile's own home and credential scope; `gateway/run.py:8582` stamps inbound events with the owning profile.",
      "**Per-channel persona/context** is handled by the `channel_prompts` config key:\n- Set distinct ephemeral system prompts per channel/group ID in your platform config"
    ]
  },
  {
    "question": "How do authentication requirements differ between using Google Gemini and Anthropic Claude Pro/Max subscription allowances in Hermes Agent?",
    "answer": "Google Gemini must be configured with an API key (`GOOGLE_API_KEY` or `GEMINI_API_KEY`) because CLI OAuth was removed, whereas utilizing Anthropic Pro/Max subscription allowances requires OAuth authentication rather than an API key.",
    "evidence": [
      "Current supported Gemini setup is Google AI Studio with `GOOGLE_API_KEY` or `GEMINI_API_KEY` (`plugins/model-providers/gemini/__init__.py:51-59`",
      "To use your Pro/Max subscription allowance through hermes-agent, you need to authenticate via OAuth (not an API key)."
    ]
  },
  {
    "question": "What container configuration and architecture support does the official `nousresearch/hermes-agent` Docker image offer for NAS and ARM devices?",
    "answer": "The official Docker image publishes multi-architecture manifests covering `linux/amd64` and `linux/arm64` (ARM64/v8), and supports `PUID` and `PGID` environment variables to remap container user permissions on NAS host bind mounts.",
    "evidence": [
      "`48083211ef606f3305c09df576514ac99bc7f594` added `PUID`/`PGID` aliases for `HERMES_UID`/`HERMES_GID`, preserving canonical-variable precedence.",
      "CI now uses `docker/setup-qemu-action` for cross-compilation and publishes a multi-arch manifest covering `linux/amd64` and `linux/arm64`."
    ]
  }
]
